import {esc,icon,empty} from './ui.js';
const pct=v=>v==null?'—':`${(Number(v)*100).toFixed(1)}%`;
const pp=v=>v==null?'—':`${Number(v)>0?'+':''}${Math.abs(Number(v))>0&&Math.abs(Number(v))<.1?Number(v).toFixed(3):Number(v).toFixed(1)} pp`;
const option=(value,label,current)=>`<option value="${esc(value)}" ${value===current?'selected':''}>${esc(label)}</option>`;
export function renderScopeFilters(data,state,loading){
 const options=data?.filterOptions??{customers:[],statuses:['生产中','已完工','未开工','待确认'],risks:['严重','重点','注意','数据不足','缺少基线','不可评级','正常','优于预期']};
 return `<div class="bm-range-actions"><select class="control" id="bm-mode" aria-label="对照基线">${option('ideal','理想上界',state.mode)}${option('budget','含损耗预算',state.mode)}</select><input class="control" type="date" id="bm-date" aria-label="业务截至日期" value="${esc(state.asOf)}"><button class="button primary" id="bm-refresh" ${loading?'disabled':''}>${icon('refresh')}${loading?'读取中…':'刷新数据'}</button></div><section class="bm-filterbar" aria-label="订单监测范围"><select class="control" id="bm-customer" aria-label="客户">${option('','全部客户',state.customer)}${options.customers.map(c=>option(c,c,state.customer)).join('')}</select><select class="control" id="bm-status" aria-label="生产状态">${option('','全部状态',state.status)}${options.statuses.map(s=>option(s,s==='已完工'?'已完工':s,state.status)).join('')}</select><select class="control" id="bm-risk" aria-label="风险等级">${option('','全部风险',state.risk)}${options.risks.map(r=>option(r,r,state.risk)).join('')}</select><select class="control" id="bm-period" aria-label="趋势时间范围">${[7,16,30].map(n=>option(String(n),`近 ${n} 天趋势`,String(state.period))).join('')}</select><label class="bm-global-search">${icon('search')}<input class="control" id="bm-search" type="search" value="${esc(state.search)}" placeholder="搜索订单号、产品或客户" aria-label="搜索订单"></label><button class="bm-reset" id="bm-reset">重置筛选</button></section>`;
}
const badgeClass={'严重':'severe','重点':'key','注意':'attention','数据不足':'unknown','缺少基线':'unknown','不可评级':'unknown','正常':'normal','优于预期':'better'};
function pageNumbers(current,total){if(total<=7)return Array.from({length:total},(_,i)=>i+1);const values=new Set([1,total,current-1,current,current+1]);if(current<4)[2,3,4].forEach(x=>values.add(x));if(current>total-3)[total-3,total-2,total-1].forEach(x=>values.add(x));return [...values].filter(x=>x>=1&&x<=total).sort((a,b)=>a-b);}
export function renderOrdersTable(data,rows,page,pages,state){
 const count=rows.length,first=count?(state.page-1)*6+1:0,last=Math.min(state.page*6,count);let lastPage=0;
 const numbers=pageNumbers(state.page,pages).map(n=>{const gap=n-lastPage>1?'<span class="bm-pagination-gap">…</span>':'';lastPage=n;return `${gap}<button class="bm-page ${n===state.page?'active':''}" data-bm-page="${n}" aria-label="第 ${n} 页" ${n===state.page?'aria-current="page"':''}>${n}</button>`;}).join('');
 return `<section class="panel bm-orders"><div class="table-top"><h2>订单监测 <span class="count">${count} 笔订单</span></h2><div class="bm-table-tools">${state.filter?`<span class="bm-list-filter">列表：${esc(state.filter==='deteriorated'?'今日恶化':state.filter==='incomplete'?'待补齐':data.distribution.find(b=>b.key===state.filter)?.label??state.filter)} <button id="bm-clear-list" aria-label="清除列表分类筛选">×</button></span>`:''}<span>按风险优先跟进</span><select class="control" id="bm-sort" aria-label="订单排序">${option('risk','风险优先',state.sort)}${option('deviation','毛利率偏差从低到高',state.sort)}${option('yesterday','较昨日变化从低到高',state.sort)}${option('id','订单号升序',state.sort)}</select></div></div><div class="table-wrap bm-orders-table"><table><thead><tr><th>订单 / 产品</th><th>客户</th><th>生产进度</th><th>预期毛利率</th><th>当前毛利率</th><th>较预期偏差</th><th>较昨日变化</th><th>风险等级</th><th>操作</th></tr></thead><tbody>${page.map(row=>`<tr><td><button class="bm-order-name" data-bm-select="${esc(row.order.id)}">${esc(row.order.id)}</button><small>${esc(row.order.product)}</small></td><td>${esc(row.order.customer||'未提供')}</td><td><div class="bm-production-progress"><span class="bm-progress-track"><i style="width:${row.cumulative.progress==null?0:Math.min(100,Math.max(0,Number(row.cumulative.progress)*100))}%"></i></span><span>${pct(row.cumulative.progress)}</span></div></td><td>${pct(row.cumulative.expected.margin)}</td><td class="${row.cumulative.actual.margin!=null&&Number(row.cumulative.actual.margin)<0?'negative':''}">${pct(row.cumulative.actual.margin)}</td><td class="${row.marginDeviationPp!=null&&Number(row.marginDeviationPp)<0?'negative':row.marginDeviationPp!=null&&Number(row.marginDeviationPp)>0?'positive':''}">${pp(row.marginDeviationPp)}</td><td class="${row.comparison.marginChangePp!=null&&Number(row.comparison.marginChangePp)<0?'negative':''}" title="${esc(row.comparison.reasons.join('；')||'前后日当日毛利率变化')}">${pp(row.comparison.marginChangePp)}</td><td><span class="bm-risk-badge ${badgeClass[row.risk?.label]??'unknown'}" title="${esc(row.risk?.reason??'当前版本尚未提供风险分级')}"><i></i>${esc(row.risk?.label??'不可评级')}</span></td><td><a class="link" href="#imported/${encodeURIComponent(row.order.id)}?asOf=${encodeURIComponent(data.scope.asOf)}&amp;revision=${encodeURIComponent(row.revisionId)}&amp;baselineMode=${encodeURIComponent(data.scope.baselineMode)}">查看分析</a><button class="link bm-row-evidence" data-bm-evidence="${esc(row.snapshotId)}">依据</button></td></tr>`).join('')}</tbody></table></div>${!count?empty('暂无符合条件的订单','调整客户、状态、风险或搜索条件后再试。'):''}<div class="table-bottom"><span>共 ${count} 笔 · ${first}–${last} 笔 · pp 表示百分点 <small>较昨日按当日毛利率比较</small></span><nav class="bm-pagination" aria-label="订单分页"><button class="bm-page" id="bm-prev" aria-label="上一页" ${state.page===1?'disabled':''}>${icon('back')}</button>${numbers}<button class="bm-page" id="bm-next" aria-label="下一页" ${state.page===pages?'disabled':''}>${icon('chevron')}</button></nav></div></section>`;
}
